package com.voiceforge.platform;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point of the VoiceForge intelligent voice platform.
 *
 * <p>Component scanning rooted at this package discovers every recreated
 * subpackage ({@code config}, {@code controller}, {@code dto}, {@code entity},
 * {@code exception}, {@code filter}, {@code mapper}, {@code service}).</p>
 */
@SpringBootApplication
public class VoiceForgeApplication {

    public static void main(String[] args) {
        SpringApplication.run(VoiceForgeApplication.class, args);
    }
}

package com.voiceforge.platform.config;

import com.voiceforge.platform.entity.HotWord;
import com.voiceforge.platform.entity.HotWordGroup;
import com.voiceforge.platform.entity.User;
import com.voiceforge.platform.mapper.HotWordGroupMapper;
import com.voiceforge.platform.mapper.HotWordMapper;
import com.voiceforge.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

/**
 * Conditional startup seeding, run after schema initialization. Restarts are
 * idempotent: each table is seeded only when it is empty.
 *
 * <p>Seeds the three login accounts (BCrypt-encoded passwords), the preset
 * hot-word group {@code 医疗术语} owned by {@code user1}, and the preset hot word
 * {@code 阿莫西林} (weight 80) in that group created by {@code user1}.</p>
 */
@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final HotWordGroupMapper hotWordGroupMapper;
    private final HotWordMapper hotWordMapper;
    private final BCryptPasswordEncoder passwordEncoder;

    public DataInitializer(UserMapper userMapper,
                           HotWordGroupMapper hotWordGroupMapper,
                           HotWordMapper hotWordMapper,
                           BCryptPasswordEncoder passwordEncoder) {
        this.userMapper = userMapper;
        this.hotWordGroupMapper = hotWordGroupMapper;
        this.hotWordMapper = hotWordMapper;
        this.passwordEncoder = passwordEncoder;
    }

    @Override
    public void run(String... args) {
        if (userMapper.count() == 0) {
            insertUser("admin", "admin123", "ADMIN");
            insertUser("user1", "user123", "USER");
            insertUser("user2", "user456", "USER");
        }

        if (hotWordGroupMapper.count() == 0) {
            User user1 = userMapper.findByUsername("user1");

            HotWordGroup group = new HotWordGroup();
            group.setName("医疗术语");
            group.setDomain("medical");
            group.setOwnerId(user1.getId());
            group.setCreatedAt(LocalDateTime.now());
            hotWordGroupMapper.insert(group);

            if (hotWordMapper.count() == 0) {
                LocalDateTime now = LocalDateTime.now();
                HotWord hotWord = new HotWord();
                hotWord.setGroupId(group.getId());
                hotWord.setText("阿莫西林");
                hotWord.setWeight(80);
                hotWord.setCreatorId(user1.getId());
                hotWord.setCreatedAt(now);
                hotWord.setUpdatedAt(now);
                hotWordMapper.insert(hotWord);
            }
        }
    }

    private void insertUser(String username, String rawPassword, String role) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setRole(role);
        user.setCreatedAt(LocalDateTime.now());
        userMapper.insert(user);
    }
}

package com.voiceforge.platform.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Issues and verifies the platform's login tokens: signed JWTs (HS256) whose
 * signing key is derived from the retained {@code jwt.secret} property, which
 * carry the username ({@code sub}) and the user's role ({@code role}), and
 * which expire {@code jwt.expiration} seconds after issuance.
 *
 * <p>Tokens follow the standard compact serialization
 * {@code base64url(header).base64url(payload).base64url(signature)} with
 * HMAC-SHA256 signatures. Malformed, tampered (bad signature), or expired
 * tokens are reported as invalid by {@link #validateToken(String)}.</p>
 */
@Component
public class JwtUtil {

    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final Base64.Encoder B64_ENCODER = Base64.getUrlEncoder().withoutPadding();
    private static final Base64.Decoder B64_DECODER = Base64.getUrlDecoder();

    @Value("${jwt.secret}")
    private String secret;

    @Value("${jwt.expiration}")
    private long expiration;

    /**
     * Generates a signed token for the given username and role, expiring
     * {@code jwt.expiration} seconds from now.
     */
    public String generateToken(String username, String role) {
        try {
            long issuedAt = Instant.now().getEpochSecond();

            Map<String, Object> header = new LinkedHashMap<>();
            header.put("alg", "HS256");
            header.put("typ", "JWT");

            Map<String, Object> claims = new LinkedHashMap<>();
            claims.put("sub", username);
            claims.put("role", role);
            claims.put("iat", issuedAt);
            claims.put("exp", issuedAt + expiration);

            String content = B64_ENCODER.encodeToString(MAPPER.writeValueAsBytes(header))
                    + "."
                    + B64_ENCODER.encodeToString(MAPPER.writeValueAsBytes(claims));
            String signature = B64_ENCODER.encodeToString(sign(content));
            return content + "." + signature;
        } catch (Exception e) {
            throw new IllegalStateException("Failed to generate JWT token", e);
        }
    }

    /**
     * Extracts the username ({@code sub} claim) from a token.
     */
    public String getUsername(String token) {
        Object value = claims(token).get("sub");
        return value == null ? null : value.toString();
    }

    /**
     * Extracts the role ({@code role} claim) from a token.
     */
    public String getRole(String token) {
        Object value = claims(token).get("role");
        return value == null ? null : value.toString();
    }

    /**
     * Reports whether the token is correctly signed and unexpired. Malformed,
     * tampered, or expired tokens count as invalid.
     */
    public boolean validateToken(String token) {
        try {
            claims(token);
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Verifies the signature and expiration of the token and returns its
     * claims; throws on any malformed, tampered, or expired token.
     */
    private Map<String, Object> claims(String token) {
        if (token == null) {
            throw new IllegalArgumentException("Token is null");
        }
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Malformed token");
        }
        byte[] expectedSignature = sign(parts[0] + "." + parts[1]);
        byte[] presentedSignature = B64_DECODER.decode(parts[2]);
        if (!MessageDigest.isEqual(expectedSignature, presentedSignature)) {
            throw new SecurityException("Token *** does not match");
        }
        try {
            @SuppressWarnings("unchecked")
            Map<String, Object> claims = MAPPER.readValue(B64_DECODER.decode(parts[1]), Map.class);
            Object exp = claims.get("exp");
            if (exp instanceof Number) {
                long expiresAt = ((Number) exp).longValue();
                if (expiresAt < Instant.now().getEpochSecond()) {
                    throw new SecurityException("Token is expired");
                }
            }
            return claims;
        } catch (SecurityException e) {
            throw e;
        } catch (Exception e) {
            throw new IllegalArgumentException("Unreadable token payload", e);
        }
    }

    private byte[] sign(String content) {
        try {
            Mac mac = Mac.getInstance(HMAC_ALGORITHM);
            mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM));
            return mac.doFinal(content.getBytes(StandardCharsets.UTF_8));
        } catch (Exception e) {
            throw new IllegalStateException("Failed to compute token ***", e);
        }
    }
}

package com.voiceforge.platform.config;

import com.voiceforge.platform.filter.JwtAuthFilter;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

/**
 * Security setup: BCrypt password *** CSRF disabled (state-changing JSON
 * requests succeed carrying only the Bearer header), stateless sessions (each
 * request is authenticated solely from its token), {@code /api/auth/login}
 * public, every other request authenticated, and {@link JwtAuthFilter}
 * registered ahead of {@link UsernamePasswordAuthenticationFilter}.
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    private final JwtAuthFilter jwtAuthFilter;

    public SecurityConfig(JwtAuthFilter jwtAuthFilter) {
        this.jwtAuthFilter = jwtAuthFilter;
    }

    @Bean
    public BCryptPasswordEncoder bCryptPasswordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
                .csrf(csrf -> csrf.disable())
                .sessionManagement(session -> session
                        .sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(auth -> auth
                        .requestMatchers("/api/auth/login").permitAll()
                        .anyRequest().authenticated())
                .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }
}

